WITH sepsis_patients AS (SELECT DISTINCT p.subject_id FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND a.admission_type = 'sepsis'), lactate_measurements AS (SELECT l.value AS lactate_level, s.subject_id FROM labevents l JOIN sepsis_patients s ON l.subject_id = s.subject_id WHERE l.itemid = 26509570) SELECT percentile_cont(0.75) within GROUP (ORDER BY lactate_level) - percentile_cont(0.25) within GROUP (ORDER BY lactate_level) AS interquartile_range FROM lactate_measurements;